<script setup lang="ts">
import {computed,ref,watch} from 'vue';
import {useRoute,useRouter} from 'vue-router';
import {managementRequest,cycleStage} from '../api/management';
import DepartmentGrowthDrawer from './DepartmentGrowthDrawer.vue';
import ArchiveCycleReport from './ArchiveCycleReport.vue';
const route=useRoute(),router=useRouter();
const records=ref<any[]>([]),detail=ref<any>(null),submissions=ref<any[]>([]),results=ref<any[]>([]),history=ref<any[]>([]),errors=ref<Record<string,string>>({}),loading=ref(false);
const start=ref(''),end=ref(''),stage=ref(''),publishedOnly=ref(false),query=ref(''),page=ref(1),pageSize=ref(10),selected=ref('');let generation=0;
const cycleId=computed(()=>String(route.params.cycleId??''));
const tab=computed(()=>String(route.query.tab??(cycleId.value?'overview':'cycles')));
const menu=computed(()=>cycleId.value?[['overview','周期概况'],['submissions','提交记录'],['scores','评分明细'],['departments','部门结果'],['history','发布历史']]:[['cycles','月评周期'],['submissions','提交记录'],['scores','评分明细'],['departments','部门结果']]);
const activeCycle=computed(()=>cycleId.value||selected.value);
const filtered=computed(()=>records.value.filter(r=>(!start.value||r.month>=start.value)&&(!end.value||r.month<=end.value)&&(!stage.value||r.status===stage.value)&&(!publishedOnly.value||r.published>0)&&(!query.value||`${r.month} ${r.title} ${r.reason??''}`.toLowerCase().includes(query.value.trim().toLowerCase()))));
const pages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/pageSize.value)));
const visible=computed(()=>filtered.value.slice((page.value-1)*pageSize.value,page.value*pageSize.value));
const drawerDepartment=ref<{id:string|null,name:string}|null>(null);
const departmentSummary=computed(()=>{const m=new Map<string,{id:string|null,name:string,count:number}>();for(const r of results.value){const id=r.department_id??null,key=id??'unassigned',item=m.get(key)??{id,name:r.department_name||'未分配',count:0};item.count++;m.set(key,item)}return [...m.values()];});
watch([start,end,stage,publishedOnly,query,pageSize],()=>{page.value=1});
watch(pages,n=>{if(page.value>n)page.value=n});
function changeTab(key:string){router.replace({path:route.path,query:{...route.query,tab:key}})}
function date(v:any){return v?new Date(v).toLocaleString('zh-CN',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}):'—'}
async function loadLedger(){try{records.value=await managementRequest('management/archive-ledger');if(!records.value.some(r=>r.id===selected.value)){const requested=String(route.query.cycleId??'');selected.value=records.value.find(r=>r.id===requested)?.id??records.value[0]?.id??'';}}catch(e){errors.value={...errors.value,ledger:String(e)}}}
async function loadDetail(){const seq=++generation;detail.value=null;submissions.value=[];results.value=[];history.value=[];errors.value={};if(!activeCycle.value)return;loading.value=true;const id=encodeURIComponent(activeCycle.value);const calls:[string,Promise<any>][]=[['overview',managementRequest(`management/cycle-detail?cycleId=${id}`)],['submissions',managementRequest(`management/submissions?cycleId=${id}`)],['scores',managementRequest(`management/archives?cycleId=${id}`)],['history',managementRequest(`management/archives?cycleId=${id}&history=true`)]];await Promise.all(calls.map(async([key,promise])=>{try{const data=await promise;if(seq!==generation)return;if(key==='overview')detail.value=data;else if(key==='submissions')submissions.value=data;else if(key==='scores')results.value=data;else history.value=data;}catch(e){if(seq===generation)errors.value={...errors.value,[key]:String(e)}}}));if(seq===generation)loading.value=false;}
watch(activeCycle,()=>{drawerDepartment.value=null;void loadDetail()},{immediate:true});
watch(()=>route.query.cycleId,v=>{if(!cycleId.value&&typeof v==='string'&&records.value.some(r=>r.id===v))selected.value=v});
void loadLedger();
</script>
<template><div class="archive"><nav class="tabs"><button v-for="[key,label] in menu" :key="key" :class="{active:tab===key}" @click="changeTab(key)">{{label}}</button></nav>
 <div v-if="cycleId" class="detail-heading"><RouterLink :to="{path:'/management/archives',query:{tab:'cycles'}}">← 返回月评档案</RouterLink><h2>{{detail?.cycle?.title??'周期详情'}}</h2></div>
 <p v-if="errors.ledger" class="error" role="alert">总账加载失败：{{errors.ledger}} <button @click="loadLedger">重试</button></p>
 <section v-if="!cycleId&&tab==='cycles'" class="panel"><div class="filters"><label>周期范围 <input v-model="start" type="month" aria-label="开始月份"> <span>至</span> <input v-model="end" type="month" aria-label="结束月份"></label><label>阶段 <select v-model="stage"><option value="">全部阶段</option><option v-for="s in ['DRAFT','PENDING_OPEN','REVIEWING','CALIBRATING','PARTIALLY_PUBLISHED','PUBLISHED','ARCHIVED','CANCELLED']" :key="s" :value="s">{{cycleStage(s)}}</option></select></label><label><input v-model="publishedOnly" type="checkbox">仅看正式发布</label><input v-model="query" class="search" placeholder="搜索周期或备注" aria-label="搜索周期或备注"></div><p v-if="start&&end&&start>end" class="error">开始月份不能晚于结束月份</p><div class="scroll"><table><thead><tr><th>周期</th><th>评价名称</th><th>阶段</th><th>有效人数</th><th>发布人数</th><th>最近发布时间</th><th>备注</th><th>操作</th></tr></thead><tbody><tr v-for="r in visible" :key="r.id"><td>{{r.month}}</td><td>{{r.title}}</td><td><span class="badge">{{cycleStage(r.status)}}</span></td><td>{{r.participants}}</td><td>{{r.published}}</td><td>{{date(r.published_at)}}</td><td>{{r.reason||'—'}}</td><td><RouterLink :to="{path:'/management/archives/'+r.id}">查看</RouterLink></td></tr></tbody></table></div><p v-if="!filtered.length" class="empty">暂无符合条件的月评周期</p><footer><span>共 {{filtered.length}} 条</span><div><button :disabled="page<=1" @click="page--">上一页</button><span>{{page}} / {{pages}}</span><button :disabled="page>=pages" @click="page++">下一页</button><select v-model.number="pageSize"><option :value="10">10 条/页</option><option :value="20">20 条/页</option><option :value="50">50 条/页</option></select></div></footer></section>
 <template v-else><div v-if="!cycleId" class="cycle-picker"><label>评价周期 <select v-model="selected"><option v-for="c in records" :key="c.id" :value="c.id">{{c.title}} · {{c.month}}</option></select></label></div><section class="panel"><p v-if="loading" role="status">正在加载档案…</p><template v-else>
 <template v-if="tab==='overview'"><p v-if="errors.overview" class="error">周期概况不可用：{{errors.overview}}</p><ArchiveCycleReport v-else-if="detail" :detail="detail" :results="results" :history="history" :score-error="errors.scores" @department="drawerDepartment=$event"/><p v-else class="empty">暂无周期概况</p></template>
 <template v-else-if="tab==='submissions'"><p v-if="errors.submissions" class="error">提交记录不可用：{{errors.submissions}}</p><template v-else><div class="scroll"><table><thead><tr><th>成员</th><th>参评资格</th><th>月报材料</th><th>自评状态</th></tr></thead><tbody><tr v-for="s in submissions" :key="s.user_id"><td>{{s.display_name}}</td><td>{{s.eligibility==='ELIGIBLE'?'有效参评':s.eligibility}}</td><td>{{s.active_version_id?'已提交':'未提交'}}</td><td>{{s.self_status==='SUBMITTED'?'已提交':s.self_status==='DRAFT'?'草稿':'未提交'}}</td></tr></tbody></table></div><p v-if="!submissions.length" class="empty">暂无提交记录</p></template></template>
 <template v-else-if="tab==='scores'"><p v-if="errors.scores" class="error">评分明细不可用：{{errors.scores}}</p><template v-else><div class="scroll"><table><thead><tr><th>成员</th><th>历史部门</th><th>发布版本</th><th>最终分</th><th>自评分</th><th>他评平均分</th><th>有效他评数量</th></tr></thead><tbody><tr v-for="r in results" :key="r.id"><td>{{r.display_name}}</td><td>{{r.department_name||'—'}}</td><td>v{{r.publication_version}}</td><td>{{r.payload_json?.final_score??'—'}}</td><td>{{r.payload_json?.self_score??'—'}}</td><td>{{r.payload_json?.final_score??'—'}}</td><td>{{r.payload_json?.peer_count??'—'}}</td></tr></tbody></table></div><p v-if="!results.length" class="empty">暂无正式发布成绩</p></template></template>
 <template v-else-if="tab==='departments'"><p v-if="errors.scores" class="error">部门结果不可用：{{errors.scores}}</p><template v-else><div class="scroll"><table><thead><tr><th>历史部门</th><th>已发布人数</th><th>操作</th></tr></thead><tbody><tr v-for="d in departmentSummary" :key="d.id??'unassigned'"><td>{{d.name}}</td><td>{{d.count}}</td><td><button class="department-link" @click="drawerDepartment=d">查看成长报告</button></td></tr></tbody></table></div><p v-if="!departmentSummary.length" class="empty">暂无部门发布结果</p></template></template>
 <template v-else-if="tab==='history'"><p v-if="errors.history" class="error">发布历史不可用：{{errors.history}}</p><template v-else><div class="scroll"><table><thead><tr><th>成员</th><th>历史部门</th><th>发布版本</th><th>发布时间</th><th>更正来源</th></tr></thead><tbody><tr v-for="r in history" :key="r.id"><td>{{r.display_name}}</td><td>{{r.department_name||'—'}}</td><td>v{{r.publication_version}}</td><td>{{date(r.published_at)}}</td><td>{{r.supersedes_id?'更正发布':'首次发布'}}</td></tr></tbody></table></div><p v-if="!history.length" class="empty">暂无发布历史</p></template></template>
 </template></section></template><DepartmentGrowthDrawer v-if="drawerDepartment" :department="drawerDepartment" :cycle="detail?.cycle" :results="results.filter((r:any)=>detail?.participants?.some((p:any)=>p.user_id===r.target_id&&p.eligibility==='ELIGIBLE'))" :participants="detail?.participants??null" @close="drawerDepartment=null"/></div></template>
<style scoped>
.archive{color:#192e50}.department-link{background:none;border:0;color:#246bfd;cursor:pointer;padding:4px}.tabs{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:24px}.tabs button{border:0;border-radius:6px;background:#fff;padding:10px 15px;color:#5f728e;cursor:pointer}.tabs button.active{color:#246bfd;box-shadow:inset 0 -2px #246bfd;font-weight:600}.panel{background:#fff;border:1px solid #e1e8f2;border-radius:12px;padding:22px;min-width:0}.filters{display:flex;flex-wrap:wrap;gap:16px;align-items:center;margin-bottom:22px}.filters label,.cycle-picker label{display:flex;gap:8px;align-items:center;color:#526983}.filters input:not([type=checkbox]),select{height:36px;border:1px solid #dce4ef;border-radius:6px;padding:0 10px;color:#243b5d;background:#fff}.search{margin-left:auto}.scroll{overflow:auto}table{width:100%;border-collapse:collapse;font-size:13px}th,td{text-align:left;padding:14px 10px;border-bottom:1px solid #edf1f7;white-space:nowrap}th{background:#f4f7fc;color:#687890;font-weight:500}td a,.detail-heading a{color:#246bfd;text-decoration:none}.badge{display:inline-block;background:#edf3ff;color:#3972db;padding:4px 8px;border-radius:6px}footer{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-top:22px;color:#73859c;font-size:13px}footer div{display:flex;align-items:center;gap:10px}footer button{border:1px solid #dce4ef;background:white;border-radius:6px;padding:7px 10px;color:#406287}footer button:disabled{opacity:.45}.empty{text-align:center;padding:36px;color:#8594aa}.error{color:#b43d42}.detail-heading{display:flex;align-items:center;gap:20px;margin-bottom:16px}.detail-heading h2{font-size:19px;margin:0}.cycle-picker{margin-bottom:18px}.overview{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:20px}.overview small{display:block;color:#8594aa;margin-bottom:8px}.overview strong{font-size:15px}@media(max-width:700px){.panel{padding:16px}.search{margin-left:0}.filters label{flex-wrap:wrap}footer{flex-wrap:wrap}}
</style>
